package music.resonance.mobile;
import org.junit.Test;import org.json.*;import static org.junit.Assert.*;
public class RecordingFallbackTest {
 @Test public void similarArtistOrLongerTitleDoesNotQualify()throws Exception{JSONObject original=new JSONObject().put("title","Moonlight").put("artist","Mira").put("duration",210),other=new JSONObject().put("id","BBBBBBBBBBB").put("title","Moonlight").put("channel","Miranda").put("duration",210);assertFalse(RecordingFallback.matches(original,other));other.put("channel","Mira").put("title","Moonlight Sonata");assertFalse(RecordingFallback.matches(original,other));}
 @Test public void temporaryBlocksNeverSearchAlternatives(){for(String raw:new String[]{"Video unavailable. HTTP Error 429","Video unavailable: try again later","Sign in to confirm you’re not a bot"}){assertTrue(DownloadFailures.pausesBatch(raw));assertFalse(RecordingFallback.unavailable(raw));}assertTrue(RecordingFallback.unavailable("Video unavailable"));assertFalse(RecordingFallback.unavailable("HTTP Error 403"));}
 @Test public void onlyCloseRecordingVersionsMatch()throws Exception{JSONObject track=new JSONObject().put("title","Moonlight").put("artist","Mira").put("duration",210).put("youtubeId","AAAAAAAAAAA"),candidate=new JSONObject().put("title","Mira - Moonlight (Official Audio)").put("channel","Mira - Topic").put("duration",211).put("id","BBBBBBBBBBB");assertTrue(RecordingFallback.matches(track,candidate));candidate.put("title","Moonlight (Live)");assertFalse(RecordingFallback.matches(track,candidate));candidate.put("title","Moonlight").put("duration",270);assertFalse(RecordingFallback.matches(track,candidate));candidate.put("duration",210).put("channel","Someone Else");assertFalse(RecordingFallback.matches(track,candidate));}
}
